const banks = [{ id: 'caixa', name: 'CAIXA', logo: '/banks/caixa.png' }, { id: 'brb', name: 'BRB', logo: '/banks/brb.png' }, { id: 'bradesco', name: 'Bradesco', logo: '/banks/bradesco.png' }, { id: 'santander', name: 'Santander', logo: '/banks/santander.png' }, { id: 'itau', name: 'Itaú', logo: '/banks/itau.png' }, { id: 'inter', name: 'inter', logo: '/banks/inter.png' }] as const
