const early = computed(() => extra.value > 0 ? result.value.installments[Math.min(extraMonth.value, result.value.installments.length) - 1] : undefined)
function exportCsv() { const data = csv(result.value.installments.map(r => ({ Parcela: r.number, Prestacao: r.payment.toFixed(2), Juros: r.interest.toFixed(2), Amortizacao: r.principal.toFixed(2), Saldo: r.balance.toFixed(2) }))); const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([data], { type: 'text/csv' })); a.download = 'simulacao-amortizacao.csv'; a.click() }
function share() { navigator.clipboard?.writeText(`Minha simulação Prontifica: parcela inicial ${brl(result.value.firstPayment)} em ${form.termMonths / 12} anos.`); window.open('https://api.whatsapp.com/send?phone=5561981910050&text=' + encodeURIComponent(`Confira minha simulação: parcela inicial ${brl(result.value.firstPayment)}.`), '_blank') }
