ent);" @blur="formatMoneyField('downPayment', $event); form.downPayment = Math.max(form.propertyValue * .2, Math.min(form.propertyValue, form.downPayment))"></label><label><span class="label">Prazo (meses)</span><input v-model.number="form.termMonths" class="input" type="number" min="12" max="480" step="12" @input="touch()" @change="form.termMonths = Math.max(12, Math.min(480, form.termMonths)); touch()"></label><label><span class="label">Renda familiar mensal</span><input value="R$ 0,00" class="input" type="text" inputmode="decimal" aria-label="Renda familiar mensal em reais" @input="updateMoney('monthlyIncome', $event)" @blur="formatMoneyField('monthlyIncome', $event)"></label><label class="md:col-span-2 lg:col-span-2"><span class="label flex justify-between">Entrada <b class="text-[#1265f3]">{{ pct(downPaymentPercent) }}</b></span><input v-model.number="downPaymentPercent" type="range" min="20" max="90" step="1" class="mt-3 w-full accent-[#1265f3]"></label><label><span class="label">Juros efetivos ao ano <span class="text-[#1265f3]">({{ banks.find(b => b.id === form.bank)?.name }} + {{ product.indexer }})</span></span><input v-model.number="form.annualRate" class="input bg-blue-50 font-bold text-[#1265f3]" type="number" min="0" step="0.01" readonly></label><label><span class="label">Sistema de amortização</span><select v-model="form.system" class="input"><option v-for="system in availableSystems" :key="system" :value="system">{{ system === 'SAC' ? 'SAC — parcelas decrescentes' : system === 'PRICE' ? 'Price — parcela fixa' : 'MIX — sistema combinado' }}</option></select></label></div><div v-if="form.program === &quot;MCMV&quot;" class="mt-5 rounded-2xl border border-blue-100 bg-blue-50 p-4 text-sm text-slate-700"><div class="flex flex-wrap items-center justify-between gap-2"><strong class="text-[#075DFF]">Minha Casa, Minha Vida</strong><span v-if="mcmv.eligible" class="rounded-full bg-white px-3 py-1 text-xs font-bold text-[#075DFF]">{{ mcmv.band }}</span><span v-